// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/health", wrapper.GetHealth)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/events", wrapper.GetEvents)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/sessions", wrapper.ListSessions)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/sessions", wrapper.CreateSession)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/sessions/{id}", wrapper.DeleteSession)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/sessions/{id}/archive", wrapper.ArchiveSession)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/sessions/{id}/reopen", wrapper.ReopenSession)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/sessions/{id}/submit", wrapper.SubmitSession)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/sessions/{id}/compact", wrapper.CompactSession)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/sessions/{id}/interrupt", wrapper.InterruptSession)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/sessions/{id}/stop", wrapper.StopSession)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/sessions/{id}/fork", wrapper.ForkSession)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/v1/sessions/{id}/agent-type", wrapper.SetSessionAgentType)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/sessions/{id}/hydration", wrapper.GetSessionHydration)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/sessions/{id}/history", wrapper.GetSessionHistory)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/sessions/{id}/code-snapshots", wrapper.GetSessionCodeSnapshots)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/sessions/{id}/revert-code", wrapper.RevertSessionCode)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/workspaces", wrapper.ListWorkspaces)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/workspaces/files/read", wrapper.ReadWorkspaceFile)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/retained-code-snapshots", wrapper.GetRetainedCodeSnapshots)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/retained-code-snapshots/revert", wrapper.RevertRetainedCode)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/configuration", wrapper.GetConfiguration)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/configuration/reload", wrapper.ReloadConfiguration)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/v1/configuration/settings", wrapper.UpdateConfigurationSettings)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/v1/agent-types/model", wrapper.SetAgentTypeModel)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/models", wrapper.ListModels)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/providers", wrapper.ListProviders)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/providers", wrapper.CreateProvider)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/providers/detail", wrapper.DeleteProviderDetail)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/providers/detail", wrapper.GetProviderDetail)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/v1/providers/detail", wrapper.UpdateProviderDetail)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/providers/discover", wrapper.DiscoverProviderCandidates)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/providers/connect", wrapper.ConnectProvider)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/providers/disconnect", wrapper.DisconnectProvider)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/providers/models", wrapper.DeleteProviderModel)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/providers/models", wrapper.ListProviderModels)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/v1/providers/models", wrapper.UpdateProviderModel)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/providers/models/discover", wrapper.DiscoverProviderModelCandidates)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/providers/fields/{field}", wrapper.ResetProviderField)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/providers/models/fields/{field}", wrapper.ResetProviderModelField)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/warnings", wrapper.GetWarnings)

	return m
}
